const assert = require('node:assert/strict');
const { chromium } = require('playwright-core');
const path = require('node:path');

(async () => {
  const [base, admin, limited, customer, job] = process.argv.slice(2);
  const browser = await chromium.launch({ executablePath: process.env.BROWSER_EXECUTABLE, headless: true, args: ['--no-sandbox'] });
  try {
    const context = await browser.newContext({ viewport: { width: 390, height: 844 } });
    await context.addCookies([{ name: 'session', value: admin, url: base, httpOnly: true }]);
    const page = await context.newPage();
    const customerURL = `${base}/customers/${customer}`;
    const change = async name => assert.equal((await context.request.post(`${base}/__fixture/${name}`)).status(), 204);
    const refresh = async label => Promise.all([page.waitForNavigation(), page.getByRole('link', { name: label, exact: true }).click()]);
    await page.goto(customerURL);
    await page.getByText('Updated at', { exact: false }).first().waitFor();
    const assets = page.getByRole('region', { name: 'Assets', exact: true });
    assert.equal(await assets.getByText('CURRENT-BROWSER-104', { exact: true }).isVisible(), true);
    assert.equal(await assets.getByText('PAST-BROWSER-104', { exact: true }).isVisible(), false);
    await assets.getByText('Past Asset associations', { exact: true }).click();
    assert.equal(await assets.getByText('PAST-BROWSER-104', { exact: true }).isVisible(), true);
    assert.doesNotMatch(await page.locator('body').innerText(), /PRIVATE NEXT CUSTOMER/);
    const work = page.getByRole('region', { name: 'Related Work', exact: true });
    const jobs = work.locator('article').filter({ hasText: 'Jobs (1)' });
    assert.equal(await jobs.getByRole('link', { name: 'View all', exact: true }).getAttribute('href'), `/customers/${customer}/work?type=job`);
    await jobs.getByRole('link', { name: 'View all', exact: true }).click();
    await page.waitForURL(`**/customers/${customer}/work?type=job`);
    assert.equal(await page.getByRole('link', { name: 'Persisted direct Job', exact: true }).count(), 1);
    await page.goto(customerURL);
    await change('contacts-off');
    await refresh('Refresh dashboard');
    assert.match(await page.locator('body').innerText(), /Contacts unavailable/);
    assert.doesNotMatch(await page.locator('body').innerText(), /No contacts/);
    assert.equal(await page.getByRole('link', { name: 'Persisted direct Job', exact: true }).count(), 1);
    await change('contacts-on');
    await refresh('Retry Contacts');
    assert.match(await page.locator('body').innerText(), /Persisted Contact/);
    const activityPattern = `**/customers/${customer}/activity*`;
    await page.route(activityPattern, route => route.abort());
    await page.reload();
    await page.getByText('Results unavailable. Previous results are not current.', { exact: true }).waitFor();
    assert.equal(await page.getByRole('link', { name: 'Persisted direct Job', exact: true }).count(), 1);
    await page.unroute(activityPattern);
    await page.getByRole('button', { name: 'Retry results', exact: true }).click();
    await page.locator('[data-results-state]').filter({ hasText: 'Results unavailable' }).waitFor({ state: 'hidden' });
    if (process.env.T104_BROWSER_EVIDENCE) await page.screenshot({ path: path.join(process.env.T104_BROWSER_EVIDENCE, 'dashboard-mobile.png'), fullPage: true });
    await change('archive-job');
    await refresh('Refresh dashboard');
    assert.equal(await page.getByRole('link', { name: 'Persisted direct Job', exact: true }).count(), 0);
    await page.getByRole('link', { name: 'Include archived Jobs', exact: true }).click();
    await page.waitForURL(`**/customers/${customer}/work?type=job&archived=1`);
    assert.match(await page.locator('body').innerText(), /Persisted direct Job/);
    assert.equal(await page.locator(`a[href="/jobs/${job}"]`).count(), 0);
    const restricted = await browser.newContext({ viewport: { width: 320, height: 740 } });
    await restricted.addCookies([{ name: 'session', value: limited, url: base, httpOnly: true }]);
    const scoped = await restricted.newPage();
    await scoped.goto(customerURL);
    assert.match(await scoped.locator('body').innerText(), /Jobs \(0\)/i);
    assert.doesNotMatch(await scoped.locator('body').innerText(), /Projects \(|Receivables|Current Assets|Persisted Contact|Create Job|Create Estimate|Create Invoice/i);
    await change('unassign');
    await change('revoke');
    await Promise.all([scoped.waitForNavigation(), scoped.getByRole('link', { name: 'Refresh dashboard', exact: true }).click()]);
    assert.doesNotMatch(await scoped.locator('body').innerText(), /Browser operational Customer|Persisted direct Job/);
    console.log('Persisted Customer dashboard: direct filtered drill-down, current/past Assets, mobile disclosure, DB-section failure/recovery, independent activity transport retry, archive refresh and revoked authority purge.');
  } finally { await browser.close(); }
})().catch(error => { console.error(error); process.exitCode = 1; });
